    internal class PurpleKindStringConverter : JsonConverter<PurpleKindString>
    {
        public override bool CanConvert(Type t) => t == typeof(PurpleKindString);

        public override PurpleKindString Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            var value = reader.GetString();
            switch (value)
            {
                case "Variable":
                    return PurpleKindString.Variable;
                case "Function":
                    return PurpleKindString.Function;
                case "Property":
                    return PurpleKindString.Property;
                case "Method":
                    return PurpleKindString.Method;
                case "Constructor":
                    return PurpleKindString.Constructor;
                case "Accessor":
                    return PurpleKindString.Accessor;
                case "Enumeration member":
                    return PurpleKindString.EnumerationMember;
                case "Module":
                    return PurpleKindString.Module;
                case "Object literal":
                    return PurpleKindString.ObjectLiteral;
            }
            throw new JsonException("Cannot unmarshal type PurpleKindString");
        }

        public override void Write(Utf8JsonWriter writer, PurpleKindString value, JsonSerializerOptions options)
        {
            switch (value)
            {
                case PurpleKindString.Variable:
                    JsonSerializer.Serialize(writer, "Variable", options);
                    return;
                case PurpleKindString.Function:
                    JsonSerializer.Serialize(writer, "Function", options);
                    return;
                case PurpleKindString.Property:
                    JsonSerializer.Serialize(writer, "Property", options);
                    return;
                case PurpleKindString.Method:
                    JsonSerializer.Serialize(writer, "Method", options);
                    return;
                case PurpleKindString.Constructor:
                    JsonSerializer.Serialize(writer, "Constructor", options);
                    return;
                case PurpleKindString.Accessor:
                    JsonSerializer.Serialize(writer, "Accessor", options);
                    return;
                case PurpleKindString.EnumerationMember:
                    JsonSerializer.Serialize(writer, "Enumeration member", options);
                    return;
                case PurpleKindString.Module:
                    JsonSerializer.Serialize(writer, "Module", options);
                    return;
                case PurpleKindString.ObjectLiteral:
                    JsonSerializer.Serialize(writer, "Object literal", options);
