    internal class FileNameConverter : JsonConverter<FileName>
    {
        public override bool CanConvert(Type t) => t == typeof(FileName);

        public override FileName Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            var value = reader.GetString();
            switch (value)
            {
                case "modules.ts":
                    return FileName.ModulesTs;
                case "classes.ts":
                    return FileName.ClassesTs;
                case "flattened.ts":
                    return FileName.FlattenedTs;
                case "access.ts":
                    return FileName.AccessTs;
                case "default-export.ts":
                    return FileName.DefaultExportTs;
                case "enumerations.ts":
                    return FileName.EnumerationsTs;
                case "functions.ts":
                    return FileName.FunctionsTs;
                case "generics.ts":
                    return FileName.GenericsTs;
                case "single-export.ts":
                    return FileName.SingleExportTs;
                case "typescript-1.3.ts":
                    return FileName.Typescript13Ts;
                case "typescript-1.4.ts":
                    return FileName.Typescript14Ts;
                case "typescript-1.5.ts":
                    return FileName.Typescript15Ts;
                case "variables.ts":
                    return FileName.VariablesTs;
            }
            throw new JsonException("Cannot unmarshal type FileName");
        }

        public override void Write(Utf8JsonWriter writer, FileName value, JsonSerializerOptions options)
        {
            switch (value)
