                    return;
                case FileName.ClassesTs:
                    JsonSerializer.Serialize(writer, "classes.ts", options);
                    return;
                case FileName.FlattenedTs:
                    JsonSerializer.Serialize(writer, "flattened.ts", options);
                    return;
                case FileName.AccessTs:
                    JsonSerializer.Serialize(writer, "access.ts", options);
                    return;
                case FileName.DefaultExportTs:
                    JsonSerializer.Serialize(writer, "default-export.ts", options);
                    return;
                case FileName.EnumerationsTs:
                    JsonSerializer.Serialize(writer, "enumerations.ts", options);
                    return;
